-- Base de un cliente FICTICIO para demostrar K-Secure. Todos los datos son sintéticos.
-- Uso: en Neon crear la base "cliente_demo", abrir el SQL Editor sobre ella, pegar este archivo y ejecutar.
DROP TABLE IF EXISTS ventas, empleados, zpagos, kna1;

-- Clientes estilo SAP: los nombres de columna no dicen qué guardan (STCD1 = RUT).
CREATE TABLE kna1 (kunnr VARCHAR(10) PRIMARY KEY, name1 VARCHAR(80), stcd1 VARCHAR(15), telf1 VARCHAR(20), smtp_addr VARCHAR(80), ort01 VARCHAR(40));

-- Pagos: ZZDATA guarda el número de tarjeta (de prueba, pasa Luhn) mezclado con otras cosas.
CREATE TABLE zpagos (id SERIAL PRIMARY KEY, kunnr VARCHAR(10), zzdata VARCHAR(60), monto INTEGER, glosa VARCHAR(120));

-- RRHH: RUN sin puntos, cuenta bancaria con contexto, patente del auto.
CREATE TABLE empleados (id SERIAL PRIMARY KEY, nombre VARCHAR(80), run VARCHAR(12), cuenta_bancaria VARCHAR(60), patente_vehiculo VARCHAR(10), correo VARCHAR(80));

-- Ventas a empresas: RUT de persona jurídica (≥ 50 millones), menos sensible.
CREATE TABLE ventas (folio INTEGER PRIMARY KEY, rut_empresa VARCHAR(15), total INTEGER);
